const iconFor = (name: string) => {
  const n = name.toLowerCase();
  if (n.includes('earbud')) return Headphones;
  if (n.includes('head')) return Headphones;
  if (n.includes('cable')) return Zap;
  if (n.includes('speaker')) return MessageCircle;
  if (n.includes('phone')) return Phone;
  if (n.includes('charger')) return Zap;
  return ShoppingBag;
};

