function useCart() {
  const [items, setItems] = useState<{ product: Product; quantity: number }[]>(() => {
    try { return JSON.parse(localStorage.getItem('mobile-nest-cart') || '[]'); } catch { return []; }
  });
  const update = (next: { product: Product; quantity: number }[]) => { setItems(next); localStorage.setItem('mobile-nest-cart', JSON.stringify(next)); };
  const add = (product: Product) => update(items.some(i => i.product.id === product.id) ? items.map(i => i.product.id === product.id ? { ...i, quantity: i.quantity + 1 } : i) : [...items, { product, quantity: 1 }]);
  const remove = (id: number) => update(items.filter(i => i.product.id !== id));
  const setQuantity = (id: number, quantity: number) => quantity < 1 ? remove(id) : update(items.map(i => i.product.id === id ? { ...i, quantity } : i));
  return { items, add, remove, setQuantity, count: items.reduce((a, i) => a + i.quantity, 0), subtotal: items.reduce((a, i) => a + i.product.price * i.quantity, 0) };
}

